using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace MonitorSlice {
static class WindowSafetyTests {
 static Rectangle Bounds(Form f){Native.Rect r;Native.GetWindowRect(f.Handle,out r);return r.Box;}
 static void Place(Form f,Rectangle r){Native.SetWindowPos(f.Handle,IntPtr.Zero,r.X,r.Y,r.Width,r.Height,0x214);}
 static void Wait(){var until=DateTime.UtcNow.AddMilliseconds(1300);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}}
 public static void Run(){var physical=Displays.All().Where(d=>d.Attached&&!Displays.Virtual().Any(v=>v.Name==d.Name)).ToArray();if(physical.Length<2)throw new Exception("이 검사는 두 물리 모니터가 필요합니다.");var a=physical[0].Mode;var b=physical[1].Mode;var hidden=new Rectangle(a.X,a.Y,a.Width,a.Height);var visible=new Rectangle(b.X,b.Y,b.Width,b.Height);var forms=new List<Form>();bool passed=false;int moved=0;try{using(var safety=new WindowSafety(hidden,new List<Viewport>{new Viewport{Source=visible,Destination=hidden}},true)){var stable=new Form{Text="CarryTest visible",StartPosition=FormStartPosition.Manual,AutoScaleMode=AutoScaleMode.None};forms.Add(stable);stable.Show();Place(stable,new Rectangle(visible.X+80,visible.Y+80,400,300));Wait();var before=Bounds(stable);var newlyOpened=new Form{Text="CarryTest new",StartPosition=FormStartPosition.Manual,AutoScaleMode=AutoScaleMode.None};forms.Add(newlyOpened);newlyOpened.Show();Place(newlyOpened,new Rectangle(hidden.X+100,hidden.Y+100,500,350));Wait();if(!WindowCarry.WorkArea(visible).Contains(Bounds(newlyOpened)))throw new Exception("새 창 자동 구조 실패");Place(newlyOpened,new Rectangle(hidden.X+160,hidden.Y+140,500,350));Wait();if(!WindowCarry.WorkArea(visible).Contains(Bounds(newlyOpened)))throw new Exception("앱 위치 재설정 후 구조 실패");var dialog=new Form{Text="CarryTest dialog",StartPosition=FormStartPosition.Manual,AutoScaleMode=AutoScaleMode.None};forms.Add(dialog);dialog.Show(stable);Place(dialog,new Rectangle(hidden.X+120,hidden.Y+120,300,200));Wait();if(!WindowCarry.WorkArea(visible).Contains(Bounds(dialog)))throw new Exception("소유 대화상자 구조 실패");if(Bounds(stable)!=before)throw new Exception("보이는 모니터의 창이 이동됨");moved=safety.Moved;passed=true;}}finally{foreach(var f in forms)f.Dispose();string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"evidence","window-safety-test.json");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,new JavaScriptSerializer().Serialize(new{Passed=passed,Rescued=moved,NewWindow=true,RepositionedWindow=true,OwnedDialog=true,VisibleWindowUnchanged=true,ChangesDisplayTopology=false}));}}
}
}
